use crate::{ValueError,ValueRefusalKind,NativeDecodeControl,native_decoding::NativeDecodeProgress};
#[test]
fn paged_semantic_text_keeps_actual8194_success_and_partial_cancellation_owners_under4096(){
 use crate::{NativeDecodeControl,ValueRefusalKind,paged_text::{PagedTextDecodeFrame,PagedTextReadStep,PagedTextStage}};
 use std::{io::Write,process::{Command,Stdio}};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/📝️paged-text.json")).unwrap();let mut actual=Vec::new();
 for row in fixture["cases"].as_array().unwrap(){
  let input=if row["source"]=="unicode"{format!("{}{}{}{}","x".repeat(4095),fixture["unicode"]["middle"].as_str().unwrap(),"x".repeat(4093),fixture["unicode"]["tail"].as_str().unwrap()).into_bytes()}else{vec![fixture["ascii"]["byte"].as_u64().unwrap()as u8;fixture["ascii"]["repetitions"].as_u64().unwrap()as usize]};assert_eq!(input.len(),8194);let pointer=input.as_ptr();let original=crate::staged_rig::source(input);let mode=row["mode"].as_str().unwrap();let mut observer=|_|true;let mut control=NativeDecodeControl::new(if mode=="initial"{4096}else{131072},&mut observer);let mut physical=crate::OriginalConstructionAuthority::new(crate::staged_rig::Physical{interrupt:false,submitted:Default::default()});let mut work=crate::OriginalWorkAuthority::new(crate::staged_rig::Work);let mut output=None;let mut frame=PagedTextDecodeFrame::<131072>::new(&mut output).unwrap();let mut completed=false;let mut canceled=false;let mut owned_failure=None;
  for _ in 0..100000{let stage=frame.stage();if ((mode=="validate-cancel"&&stage==PagedTextStage::Validating)||(mode=="materialize-cancel"&&stage==PagedTextStage::Copying))&&frame.phase_progress().0==256{canceled=true;break}let turn=crate::staged_rig::decode_turn(&mut frame,&original,&mut control,&mut physical,&mut work);match turn.result{Ok(PagedTextReadStep::Complete(_))=>{completed=true;break},Ok(PagedTextReadStep::Progress(_)|PagedTextReadStep::Pending)=>{},Err(failure)=>{owned_failure=Some(failure);break},Ok(PagedTextReadStep::Denied)=>panic!("fully quoted original decoder was denied")}}
  let logical=frame.retained_len();let allocated=frame.retained_capacity();assert_eq!(control.owned_bytes(),allocated);assert_eq!(original.borrow().get().as_ptr(),pointer);assert_eq!(original.borrow().get().len(),8194);
  let error=if canceled{Some("canceled")}else if let Some(ref failure)=owned_failure{let receiving=&failure.receiving;let kind=failure.child.as_ref().or(failure.work_refusal.as_ref()).or(receiving.primary.as_ref()).or(receiving.quote_refusal.as_ref()).or(receiving.allocation_refusal.as_ref()).or(receiving.work_refusal.as_ref()).or(receiving.work_overrun.as_ref()).or_else(||receiving.allocation_failure.as_ref().and_then(|failure|failure.primary.as_ref().or(failure.admission.as_ref()).or(failure.extent.as_ref()))).or_else(||receiving.native_allocation.as_ref().and_then(|failure|failure.primary.as_ref().or(failure.extent_refusal.as_ref()))).map(|error|error.kind);assert_eq!(kind,Some(ValueRefusalKind::OwnershipLimit));Some("ownership")}else{assert!(completed);None};
  assert_eq!(logical,row["logical"].as_u64().unwrap()as usize);assert_eq!(error.map(serde_json::Value::from).unwrap_or(serde_json::Value::Null),row["error"]);if mode=="initial"{assert!(allocated>0&&allocated<=4096)}if mode=="materialize-cancel"{assert!(allocated>=4096)}if let Some(failure)=owned_failure{crate::staged_rig::close_owned_failure(failure)}let disposed=crate::staged_rig::close_decode_frame(&mut frame);drop(frame);let mut octets=Vec::new();if completed{let text=output.take().expect("actual original text was published");assert_eq!(text.borrow().unwrap().byte_len(),8194);assert!(text.borrow().unwrap().bytes().eq(original.borrow().get().iter().copied()));assert_eq!(text.borrow().unwrap().chars().collect::<String>().as_bytes(),original.borrow().get().as_slice());octets=text.borrow().unwrap().bytes().collect();assert_eq!(crate::staged_rig::close_text(text),allocated)}else{assert!(output.is_none());assert_eq!(disposed,allocated)}drop(control);assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());crate::staged_rig::close_source(original);actual.push(serde_json::json!({"id":row["id"],"error":error,"logical":logical,"octets":octets}));
 }
 for bytes in fixture["invalidUtf8"].as_array().unwrap(){let input:Vec<u8>=serde_json::from_value(bytes.clone()).unwrap();let original=crate::staged_rig::source(input);let mut observer=|_|true;let mut control=NativeDecodeControl::new(131072,&mut observer);let mut physical=crate::OriginalConstructionAuthority::new(crate::staged_rig::Physical{interrupt:false,submitted:Default::default()});let mut work=crate::OriginalWorkAuthority::new(crate::staged_rig::Work);let mut output=None;let mut frame=PagedTextDecodeFrame::<131072>::new(&mut output).unwrap();let mut refusal=None;for _ in 0..1000{let turn=crate::staged_rig::decode_turn(&mut frame,&original,&mut control,&mut physical,&mut work);match turn.result{Err(error)=>{refusal=Some(error);break},Ok(PagedTextReadStep::Progress(_)|PagedTextReadStep::Pending)=>{},_=>panic!("malformed UTF8 was published")}}let refusal=refusal.expect("original malformed source was refused");assert_eq!(refusal.child.as_ref().unwrap().kind,ValueRefusalKind::InvalidValue);assert_eq!(frame.retained_capacity(),0);assert_eq!(control.owned_bytes(),0);crate::staged_rig::close_owned_failure(refusal);assert_eq!(crate::staged_rig::close_decode_frame(&mut frame),0);drop(frame);assert!(output.is_none());drop(control);assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());crate::staged_rig::close_source(original);}
    let script="const x=JSON.parse(await Bun.stdin.text());const f=x.fixture,ascii=Uint8Array.from({length:f.ascii.repetitions},()=>f.ascii.byte),unicode=new TextEncoder().encode(String.fromCharCode(f.unicode.prefixByte).repeat(f.unicode.prefixRepetitions)+f.unicode.middle+String.fromCharCode(f.unicode.suffixByte).repeat(f.unicode.suffixRepetitions)+f.unicode.tail);if(ascii.length!==8194||unicode.length!==8194)throw Error('independent exact extents');for(const v of f.invalidUtf8){let refused=false;try{new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(v));}catch{refused=true;}if(!refused)throw Error('invalid UTF8 accepted');}await Bun.write(Bun.stdout,JSON.stringify(f.cases.map(c=>({id:c.id,error:c.error,logical:c.logical,octets:c.error===null?Array.from(c.source==='ascii'?ascii:unicode):[]}))));";
    let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(serde_json::json!({"fixture":fixture}).to_string().as_bytes()).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));assert_eq!(actual,serde_json::from_slice::<Vec<serde_json::Value>>(&output.stdout).unwrap());
}


#[test]
fn paged_semantic_text_encoding_source_retains_full8194_and_partial4096(){
 use crate::{NativeEncodeControl,paged_text::{PagedText,PagedTextEncodeFrame,PagedTextReadStep,PagedTextStage}};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🧾️semantic-text-retirement/🔣️.json")).unwrap();let text=fixture["text"].as_str().unwrap().repeat(fixture["textBytes"].as_u64().unwrap()as usize);assert_eq!(text.len(),8194);assert_eq!(fixture["maximumBytes"],4096);assert_eq!(fixture["maximumItems"],1);let original=crate::staged_rig::source(text);
 {let mut allow=|_|true;let mut encoding=NativeEncodeControl::new(65536,&mut allow);let mut physical=crate::OriginalConstructionAuthority::new(crate::staged_rig::Physical{interrupt:false,submitted:Default::default()});let mut work=crate::OriginalWorkAuthority::new(crate::staged_rig::Work);let owner=crate::staged_rig::encode_success::<_,20000>(&original,&mut encoding,&mut physical,&mut work,20000,"","");assert!(owner.borrow().unwrap().bytes().eq(original.borrow().get().bytes()));assert_eq!(encoding.owned_bytes(),owner.allocated_bytes());let admitted=encoding.owned_bytes();assert_eq!(crate::staged_rig::close_text(owner),admitted);drop(encoding);assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());}
 for initial in [true,false]{let mut allow=|_|true;let mut encoding=NativeEncodeControl::new(if initial{4096}else{65536},&mut allow);let mut physical=crate::OriginalConstructionAuthority::new(crate::staged_rig::Physical{interrupt:false,submitted:Default::default()});let mut work=crate::OriginalWorkAuthority::new(crate::staged_rig::Work);let mut output:Option<PagedText<20000>>=None;let mut frame=PagedTextEncodeFrame::new(&mut output,20000).unwrap();let mut stopped=false;
  for _ in 0..100000{if !initial&&frame.stage()==PagedTextStage::Copying&&frame.phase_progress().0==256{stopped=true;break}let turn=crate::staged_rig::encode_turn(&mut frame,&original,&mut encoding,&mut physical,&mut work);match turn.result{Ok(PagedTextReadStep::Progress(_)|PagedTextReadStep::Pending)=>{},Err(failure)if initial=>{crate::staged_rig::close_encode_failure(failure);stopped=true;break},_=>panic!("original cancellation or ownership refusal was lost")}}assert!(stopped);if initial{assert_eq!(frame.retained_len(),0);assert!(frame.retained_capacity()>0);assert!(frame.retained_capacity()<=4096)}else{assert_eq!(frame.retained_len(),256);assert!(frame.retained_capacity()>=4096)}let admitted=frame.retained_capacity();assert_eq!(encoding.owned_bytes(),admitted);assert_eq!(crate::staged_rig::close_encode_frame(&mut frame),admitted);drop(frame);assert!(output.is_none());drop(encoding);assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());
 }crate::staged_rig::close_source(original);
}

#[test]
fn paged_semantic_text_parent_retains_original8194_actual_allocations_until4096_disposal(){
    use crate::{NativeDecodeControl,ErasedSnapshotRetirement,paged_text::PagedText,retirement::allocation_return::{ParentAllocationReturn,AllocationReturnStep}};
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/📦️text-parent/🔣️.json")).unwrap();let text=fixture["text"].as_str().unwrap().repeat(fixture["textBytes"].as_u64().unwrap()as usize);assert_eq!(text.len(),8194);assert_eq!(fixture["maximumItems"],1);assert_eq!(fixture["maximumBytes"],4096);
    let original=crate::staged_rig::source(text);let mut construction=crate::OriginalConstructionAuthority::new(crate::staged_rig::Physical{interrupt:false,submitted:Default::default()});let mut work=crate::OriginalWorkAuthority::new(crate::staged_rig::Work);let mut allow=|_|true;let mut decoding=NativeDecodeControl::new(65536,&mut allow);let mut owner=crate::staged_rig::decode_success::<_,{isize::MAX as usize}>(&original,&mut decoding,&mut construction,&mut work);assert!(owner.borrow().unwrap().bytes().eq(original.borrow().get().bytes()));let actual=owner.allocated_bytes();assert_eq!(decoding.owned_bytes(),actual);let mut parent=ParentAllocationReturn::<64>::try_new(4096,actual).unwrap();assert!(!owner.return_one(&mut parent,0).unwrap().progressed);assert_eq!(owner.byte_len(),8194);assert!(owner.borrow().is_ok());assert_eq!(parent.retained_bytes(),0);let mut returned=0;
    for _ in 0..8194+128{if owner.terminal_is_empty(){break;}let before=owner.allocated_bytes();let progress=owner.return_one(&mut parent,1).unwrap();assert!(progress.progressed);assert_eq!(before-owner.allocated_bytes(),progress.returned_allocation_bytes);returned+=progress.returned_allocation_bytes;assert!(owner.borrow().is_err());}assert!(owner.terminal_is_empty());assert_eq!(returned,actual);assert_eq!(parent.retained_bytes(),actual);assert!(!parent.terminal_is_empty());let mut physical=0;for _ in 0..128{match parent.close_step(1,4096){AllocationReturnStep::Complete=>break,AllocationReturnStep::Pending{released_items,released_bytes}=>{assert!(released_items<=1);assert!(released_bytes<=4096);physical+=released_bytes;}}}assert!(parent.terminal_is_empty());assert_eq!(physical,actual);drop(decoding);assert!(!work.has_live_actions());assert!(work.into_recipient().is_ok());assert!(construction.into_recipient().is_ok());crate::staged_rig::close_source(original);
}

struct PagedFormatterProbe{body:String,refuse_finish:bool,overlong:bool,reads:std::sync::atomic::AtomicUsize}
impl crate::paged_text::TextReadSource for PagedFormatterProbe{
 fn byte_len(&self)->usize{if self.overlong&&self.reads.load(std::sync::atomic::Ordering::SeqCst)<8181*2{8181}else{self.body.len()}}
 fn byte_at(&self,index:usize)->Option<u8>{self.reads.fetch_add(1,std::sync::atomic::Ordering::SeqCst);self.body.as_bytes().get(index).copied()}
 fn finish_recorded(&self,mut reply:crate::paged_text::TextSourceFinishReply<'_,'_>)->crate::paged_text::TextSourceFinishComplete{let _=reply.performed(1).expect("original Work receipt must accept the source report");reply.complete(if self.overlong{Err(crate::ValueError::invariant("original formatter exceeded its declared extent"))}else if self.refuse_finish{Err(crate::ValueError::literal(crate::ValueRefusalKind::Canceled,"original formatter refused after full output"))}else{Ok(())},1)}
}
impl crate::RetireOwned for PagedFormatterProbe{
 type RetirementCursor=<(String,bool,bool,usize) as crate::RetireOwned>::RetirementCursor;
 fn retirement_seed(self)->Self::RetirementCursor{crate::RetireOwned::retirement_seed((self.body,self.refuse_finish,self.overlong,self.reads.into_inner()))}
 fn retirement_birth_bytes(&self)->Option<usize>{Some(std::mem::size_of::<Self::RetirementCursor>())}
 fn controlled_retirement_supported()->bool{<(String,bool,bool,usize) as crate::RetireOwned>::controlled_retirement_supported()}
}

#[test]
fn paged_semantic_text_stream_formats_full8194_and_retains_every_refusal(){
 use crate::{NativeEncodeControl,paged_text::{PagedText,PagedTextEncodeFrame,PagedTextReadStep,PagedTextStage}};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🌊️text-stream/🔣️.json")).unwrap();assert_eq!(fixture["sourceBytes"],8194);assert_eq!(fixture["maximumAllocationBytes"],65536);assert_eq!(fixture["initialAllocationBytes"],4096);assert_eq!(fixture["maximumItems"],1);assert_eq!(fixture["maximumBytes"],4096);
 let body="x".repeat(8181);let original=crate::staged_rig::source(PagedFormatterProbe{body:body.clone(),refuse_finish:false,overlong:false,reads:Default::default()});
 let mut allow=|_|true;let mut control=NativeEncodeControl::new(65536,&mut allow);let mut physical=crate::OriginalConstructionAuthority::new(crate::staged_rig::Physical{interrupt:false,submitted:Default::default()});let mut work=crate::OriginalWorkAuthority::new(crate::staged_rig::Work);
 let owner=crate::staged_rig::encode_success::<_,{isize::MAX as usize}>(&original,&mut control,&mut physical,&mut work,8194,"Set label to ","");assert!(owner.borrow().unwrap().bytes().eq(b"Set label to ".iter().copied().chain(body.bytes())));let allocated=owner.allocated_bytes();assert_eq!(allocated,control.owned_bytes());assert_eq!(crate::staged_rig::close_text(owner),allocated);drop(control);assert!(physical.into_recipient().is_ok());assert!(work.into_recipient().is_ok());crate::staged_rig::close_source(original);
 for mode in ["initial","interior","ignored","producer","segment"]{
  let original=crate::staged_rig::source(PagedFormatterProbe{body:if mode=="ignored"{body.clone()+"too many octets after real prefix"}else{body.clone()},refuse_finish:mode=="producer",overlong:mode=="ignored",reads:Default::default()});let mut allow=|_|true;let mut control=NativeEncodeControl::new(if mode=="initial"{4096}else{65536},&mut allow);let mut physical=crate::OriginalConstructionAuthority::new(crate::staged_rig::Physical{interrupt:false,submitted:Default::default()});let mut work=crate::OriginalWorkAuthority::new(crate::staged_rig::Work);let mut output:Option<PagedText<{isize::MAX as usize}>>=None;let mut frame=PagedTextEncodeFrame::formatter(&mut output,if mode=="segment"{128}else{8194},"Set label to ","").unwrap();let mut stopped=false;
  for _ in 0..100000{if mode=="interior"&&frame.stage()==PagedTextStage::Copying&&frame.phase_progress().0==256{frame.begin_close();stopped=true;break}let turn=crate::staged_rig::encode_turn(&mut frame,&original,&mut control,&mut physical,&mut work);match turn.result{Ok(PagedTextReadStep::Progress(_)|PagedTextReadStep::Pending)=>{},Err(failure)=>{crate::staged_rig::close_encode_failure(failure);stopped=true;break},_=>panic!("refused producer published: {mode}")}}
  assert!(stopped,"producer did not stop: {mode}");if mode=="ignored"{let turn=crate::staged_rig::encode_turn(&mut frame,&original,&mut control,&mut physical,&mut work);let failure=match turn.result{Err(failure)=>failure,_=>panic!("original overflow was ignored")};crate::staged_rig::close_encode_failure(failure)}if mode=="initial"{assert_eq!(frame.retained_len(),0);assert!(frame.retained_capacity()>0&&frame.retained_capacity()<=4096)}if mode=="interior"{assert_eq!(frame.retained_len(),256)}if matches!(mode,"producer"|"ignored"){assert_eq!(frame.retained_len(),8194)}if mode=="segment"{assert_eq!(frame.retained_len(),0)}let allocated=frame.retained_capacity();assert_eq!(allocated,control.owned_bytes());assert_eq!(crate::staged_rig::close_encode_frame(&mut frame),allocated);drop(frame);assert!(output.is_none());drop(control);assert!(physical.into_recipient().is_ok());assert!(work.into_recipient().is_ok());crate::staged_rig::close_source(original);
 }
}

